// record a player's latest score and read their rank
async function submitScore(playerId, score) {
  await redis.zadd('board', score, playerId);     // store the score
}

async function getRank(playerId) {
  const rank = await redis.zrank('board', playerId); // index in ascending order
  return rank + 1;                                   // 1-based rank
}
